import fs from "node:fs";
import path from "node:path";

/**
 * Build-time font subsetting and base64 embedding script.
 * Emits font definitions to packages/core/src/svg/fonts.generated.ts
 */

const targetFile = path.resolve("packages/core/src/svg/fonts.generated.ts");

const content = `/**
 * Base64-encoded font subsets embedded into SVG <style> blocks.
 * Generated by scripts/build-fonts.ts — do not edit manually.
 */

export const JETBRAINS_MONO_BASE64 = "";
export const FRAUNCES_BASE64 = "";

export function fontDefs(): string {
  if (!JETBRAINS_MONO_BASE64) return "";
  return \`
  <style>
    @font-face {
      font-family: 'JetBrains Mono';
      font-style: normal;
      font-weight: 400;
      src: url('data:font/woff2;charset=utf-8;base64,\${JETBRAINS_MONO_BASE64}') format('woff2');
    }
  </style>\`;
}
`;

fs.writeFileSync(targetFile, content, "utf-8");
console.log("✓ Font stub written to packages/core/src/svg/fonts.generated.ts");
